import assert from "assert";

import { Dump } from "boytacean";

import {
    CARTRIDGE_BAUD_RATE,
    CARTRIDGE_FILTERS,
    CartridgeDumper,
    CartridgeExchange,
    CartridgePort,
    hasCartridgeSupport,
    readCartridge,
    requestCartridgePort
} from "../../ts/cartridge";

/**
 * A step of the scripted conversation with the fake device, the bytes
 * the dumper sends and the chunks the device replies with.
 */
type Step = {
    send: number[];
    expect: number;
    reply: number[][];
};

/**
 * A fake dumper that runs a scripted sequence of exchanges, recording
 * the replies it is fed and which of its objects have been freed.
 */
class FakeDumper implements CartridgeDumper {
    fed: number[][] = [];
    freed = false;
    exchangesFreed = 0;
    failFeed = false;
    private index = 0;

    constructor(private steps: Step[]) {}

    next_exchange(): CartridgeExchange | undefined {
        const step = this.steps[this.index];
        if (!step) return undefined;
        this.index++;
        return {
            send_eager: () => new Uint8Array(step.send),
            expect: () => step.expect,
            free: () => {
                this.exchangesFreed++;
            }
        };
    }

    feed_wa(data: Uint8Array) {
        if (this.failFeed)
            throw new Error("Invalid acknowledgement from the device");
        this.fed.push(Array.from(data));
    }

    progress(): number {
        return this.index / this.steps.length;
    }

    device(): string | undefined {
        return "GBxCart RW v1.3 (firmware L1)";
    }

    finish_wa(): Dump {
        return { title: () => "PETAL LANES" } as unknown as Dump;
    }

    free() {
        this.freed = true;
    }
}

/**
 * A fake Web Serial API port that replies to each write with the chunks
 * of the next step, recording what was written and its state.
 */
type FakePort = CartridgePort & {
    written: number[][];
    baudRate?: number;
    closed: boolean;
    end: () => void;
};

/**
 * Builds a fake serial port that replies with the chunks of each one
 * of the provided steps, in order, as data is written to it.
 *
 * @param steps The steps with the chunks of the replies.
 * @returns The fake serial port.
 */
const buildPort = (steps: Step[]): FakePort => {
    let controller: ReadableStreamDefaultController<Uint8Array>;
    let index = 0;
    const port: FakePort = {
        written: [],
        closed: false,
        readable: new ReadableStream<Uint8Array>({
            start: (value) => {
                controller = value;
            }
        }),
        writable: new WritableStream<Uint8Array>({
            write: (chunk) => {
                port.written.push(Array.from(chunk));
                const step = steps[index++];
                step?.reply.forEach((data) =>
                    controller.enqueue(new Uint8Array(data))
                );
            }
        }),
        open: async ({ baudRate }) => {
            port.baudRate = baudRate;
        },
        close: async () => {
            port.closed = true;
        },
        end: () => controller.close()
    };
    return port;
};

/**
 * The conversation of a short dump, with a firmware query, a command
 * without reply and a read of four bytes.
 */
const STEPS: Step[] = [
    {
        send: [0xa1],
        expect: 9,
        reply: [[0x08, 0x4c, 0x00, 0x01, 0x04, 0x65, 0xe2, 0x1d, 0xea]]
    },
    { send: [0xa8], expect: 0, reply: [] },
    { send: [0xb1], expect: 4, reply: [[0x50, 0x4c, 0x67, 0x00]] }
];

describe("Cartridge", function () {
    describe("#hasCartridgeSupport()", function () {
        const navigator = Object.getOwnPropertyDescriptor(
            globalThis,
            "navigator"
        );

        afterEach(() => {
            if (navigator) {
                Object.defineProperty(globalThis, "navigator", navigator);
            } else {
                delete (globalThis as { navigator?: unknown }).navigator;
            }
        });

        it("should be able to detect the lack of the Web Serial API", () => {
            Object.defineProperty(globalThis, "navigator", {
                value: {},
                configurable: true
            });
            assert.strictEqual(hasCartridgeSupport(), false);
        });

        it("should be able to detect the Web Serial API", () => {
            Object.defineProperty(globalThis, "navigator", {
                value: { serial: {} },
                configurable: true
            });
            assert.strictEqual(hasCartridgeSupport(), true);
        });
    });

    describe("#requestCartridgePort()", function () {
        const navigator = Object.getOwnPropertyDescriptor(
            globalThis,
            "navigator"
        );

        afterEach(() => {
            if (navigator) {
                Object.defineProperty(globalThis, "navigator", navigator);
            } else {
                delete (globalThis as { navigator?: unknown }).navigator;
            }
        });

        it("should be able to request a port of a GBxCart RW", async () => {
            const port = buildPort([]);
            let filters: unknown;
            Object.defineProperty(globalThis, "navigator", {
                value: {
                    serial: {
                        requestPort: async (options: { filters: unknown }) => {
                            filters = options.filters;
                            return port;
                        }
                    }
                },
                configurable: true
            });
            assert.strictEqual(await requestCartridgePort(), port);
            assert.deepStrictEqual(filters, CARTRIDGE_FILTERS);
        });
    });

    describe("#readCartridge()", function () {
        it("should be able to read a cartridge", async () => {
            const port = buildPort(STEPS);
            const dumper = new FakeDumper(STEPS);
            const progress: number[] = [];
            const { dump, device } = await readCartridge(port, {
                dumper: dumper,
                onProgress: (value) => progress.push(value)
            });
            assert.strictEqual(dump.title(), "PETAL LANES");
            assert.strictEqual(device, "GBxCart RW v1.3 (firmware L1)");
            assert.strictEqual(port.baudRate, CARTRIDGE_BAUD_RATE);
            assert.deepStrictEqual(port.written, [[0xa1], [0xa8], [0xb1]]);
            assert.deepStrictEqual(dumper.fed, [
                [0x08, 0x4c, 0x00, 0x01, 0x04, 0x65, 0xe2, 0x1d, 0xea],
                [],
                [0x50, 0x4c, 0x67, 0x00]
            ]);
            assert.deepStrictEqual(progress, [1 / 3, 2 / 3, 1]);
            assert.strictEqual(dumper.exchangesFreed, 3);
            assert.strictEqual(dumper.freed, true);
            assert.strictEqual(port.closed, true);
        });

        it("should be able to join replies split in chunks", async () => {
            const steps: Step[] = [
                {
                    send: [0xa1],
                    expect: 9,
                    reply: [
                        [0x08, 0x4c],
                        [0x00, 0x01, 0x04],
                        [0x65, 0xe2, 0x1d, 0xea]
                    ]
                }
            ];
            const dumper = new FakeDumper(steps);
            await readCartridge(buildPort(steps), { dumper: dumper });
            assert.deepStrictEqual(dumper.fed, [
                [0x08, 0x4c, 0x00, 0x01, 0x04, 0x65, 0xe2, 0x1d, 0xea]
            ]);
        });

        it("should be able to keep extra bytes for the next exchange", async () => {
            const steps: Step[] = [
                { send: [0xb4], expect: 1, reply: [[0x01, 0x50, 0x4c]] },
                { send: [0xb1], expect: 2, reply: [] },
                { send: [0xb1], expect: 1, reply: [[0x67]] }
            ];
            const dumper = new FakeDumper(steps);
            await readCartridge(buildPort(steps), { dumper: dumper });
            assert.deepStrictEqual(dumper.fed, [[0x01], [0x50, 0x4c], [0x67]]);
        });

        it("should be able to fail when the device does not reply", async () => {
            const steps: Step[] = [{ send: [0xa1], expect: 9, reply: [] }];
            const port = buildPort(steps);
            const dumper = new FakeDumper(steps);
            await assert.rejects(
                readCartridge(port, { dumper: dumper, timeout: 20 }),
                {
                    message:
                        "The device is not responding, check that it runs the L firmware"
                }
            );
            assert.strictEqual(dumper.exchangesFreed, 1);
            assert.strictEqual(dumper.freed, true);
            assert.strictEqual(port.closed, true);
        });

        it("should be able to fail on a partial reply", async () => {
            const steps: Step[] = [
                { send: [0xa1], expect: 9, reply: [[0x08, 0x4c]] }
            ];
            const port = buildPort(steps);
            await assert.rejects(
                readCartridge(port, {
                    dumper: new FakeDumper(steps),
                    timeout: 20
                }),
                { message: /not responding/ }
            );
            assert.strictEqual(port.closed, true);
        });

        it("should be able to fail when the connection is closed", async () => {
            const steps: Step[] = [{ send: [0xa1], expect: 9, reply: [] }];
            const port = buildPort(steps);
            const dumper = new FakeDumper(steps);
            port.end();
            await assert.rejects(readCartridge(port, { dumper: dumper }), {
                message: "The connection to the device was closed"
            });
            assert.strictEqual(dumper.freed, true);
            assert.strictEqual(port.closed, true);
        });

        it("should be able to fail when a reply is rejected", async () => {
            const port = buildPort(STEPS);
            const dumper = new FakeDumper(STEPS);
            dumper.failFeed = true;
            await assert.rejects(readCartridge(port, { dumper: dumper }), {
                message: "Invalid acknowledgement from the device"
            });
            assert.deepStrictEqual(port.written, [[0xa1]]);
            assert.strictEqual(dumper.exchangesFreed, 1);
            assert.strictEqual(dumper.freed, true);
            assert.strictEqual(port.closed, true);
        });

        it("should be able to fail without the streams of the port", async () => {
            const port = buildPort(STEPS);
            port.readable = null;
            const dumper = new FakeDumper(STEPS);
            await assert.rejects(readCartridge(port, { dumper: dumper }), {
                message: "Unable to access the serial port of the device"
            });
            assert.strictEqual(port.closed, true);
        });

        it("should be able to fail when the port can not be opened", async () => {
            const port = buildPort(STEPS);
            port.open = async () => {
                throw new Error("Failed to open serial port");
            };
            const dumper = new FakeDumper(STEPS);
            await assert.rejects(readCartridge(port, { dumper: dumper }), {
                message: "Failed to open serial port"
            });
            assert.deepStrictEqual(port.written, []);
            assert.strictEqual(dumper.freed, true);
        });
    });
});

import { Dump, Dumper } from "boytacean";

/**
 * The baud rate of the serial connection to a GBxCart RW.
 */
export const CARTRIDGE_BAUD_RATE = 1000000;

/**
 * The time (in milliseconds) to wait for a reply of the device,
 * which never comes when it runs another firmware.
 */
export const CARTRIDGE_TIMEOUT = 2000;

/**
 * The USB IDs of the serial converter of a GBxCart RW, used so
 * that only these devices are offered to the user.
 */
export const CARTRIDGE_FILTERS = [
    { usbVendorId: 0x1a86, usbProductId: 0x7523 }
];

/**
 * The subset of a Web Serial API port that is used to read a
 * cartridge, so that any compatible port can be used.
 */
export type CartridgePort = {
    readable: ReadableStream<Uint8Array> | null;
    writable: WritableStream<Uint8Array> | null;
    open(options: { baudRate: number }): Promise<void>;
    close(): Promise<void>;
};

/**
 * The subset of an exchange of the dumper (from the WASM package)
 * that is used to talk to the device.
 */
export type CartridgeExchange = {
    send_eager(): Uint8Array;
    expect(): number;
    free(): void;
};

/**
 * The subset of the dumper (from the WASM package) that is used to
 * read a cartridge, which holds the complete dumping logic.
 */
export type CartridgeDumper = {
    next_exchange(): CartridgeExchange | undefined;
    feed_wa(data: Uint8Array): void;
    progress(): number;
    device(): string | undefined;
    finish_wa(): Dump;
    free(): void;
};

/**
 * The result of reading a cartridge, the dump and the description
 * of the device that read it.
 */
export type CartridgeRead = {
    dump: Dump;
    device: string | undefined;
};

/**
 * Enumeration with the values for the save that is used for a game
 * loaded from a cartridge.
 */
export enum CartridgeSave {
    Cartridge = "cartridge",
    Storage = "storage",
    None = "none"
}

/**
 * The information on a cartridge that has been loaded into the
 * emulator, including the save that is used for its game.
 */
export type CartridgeInfo = {
    title: string;
    device: string | undefined;
    checksumValid: boolean;
    save: CartridgeSave;
};

/**
 * The bytes received from the device that have not been consumed
 * yet, as replies can be split or merged by the serial port.
 */
type SerialBuffer = {
    data: Uint8Array;
};

/**
 * Checks if the current environment supports the Web Serial API,
 * required to read cartridges.
 *
 * @returns If cartridges can be read in the current environment.
 */
export const hasCartridgeSupport = (): boolean => {
    return typeof navigator !== "undefined" && "serial" in navigator;
};

/**
 * Asks the user to select the serial port of a GBxCart RW, which
 * must be called as the result of a user gesture.
 *
 * @returns The serial port selected by the user.
 */
export const requestCartridgePort = async (): Promise<CartridgePort> => {
    const serial = (
        navigator as unknown as {
            serial: {
                requestPort(options: {
                    filters: typeof CARTRIDGE_FILTERS;
                }): Promise<CartridgePort>;
            };
        }
    ).serial;
    return await serial.requestPort({ filters: CARTRIDGE_FILTERS });
};

/**
 * Reads the cartridge in the GBxCart RW at the provided serial port,
 * the port is opened for the read and always closed afterwards.
 *
 * @param port The serial port of the GBxCart RW.
 * @param options The dumper to be used (defaults to the one in the
 * WASM package), which is released after the read, a callback for the progress (from 0 to 1) and the
 * timeout for each reply of the device.
 * @returns The dump of the cartridge and the device that read it.
 */
export const readCartridge = async (
    port: CartridgePort,
    {
        dumper = undefined,
        onProgress = undefined,
        timeout = CARTRIDGE_TIMEOUT
    }: {
        dumper?: CartridgeDumper;
        onProgress?: (progress: number) => void;
        timeout?: number;
    } = {}
): Promise<CartridgeRead> => {
    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    let writer: WritableStreamDefaultWriter<Uint8Array> | undefined;
    let active: CartridgeDumper | undefined = dumper;
    try {
        await port.open({ baudRate: CARTRIDGE_BAUD_RATE });
        reader = port.readable?.getReader();
        writer = port.writable?.getWriter();
        if (!reader || !writer) {
            throw new Error("Unable to access the serial port of the device");
        }

        // the dumper (always owned and released here) is only built
        // once the port is open, so that nothing is built in vain
        active = active ?? new Dumper();
        const buffer: SerialBuffer = { data: new Uint8Array(0) };
        let exchange: CartridgeExchange | undefined;
        while ((exchange = active.next_exchange())) {
            try {
                await writer.write(exchange.send_eager());
                const data = await readExact(
                    reader,
                    buffer,
                    exchange.expect(),
                    timeout
                );
                active.feed_wa(data);
            } finally {
                exchange.free();
            }
            onProgress?.(active.progress());
        }
        return { dump: active.finish_wa(), device: active.device() };
    } finally {
        // cancels any pending read before releasing the stream locks,
        // so that the port can always be closed
        await reader?.cancel().catch(() => undefined);
        reader?.releaseLock();
        writer?.releaseLock();
        await port.close().catch(() => undefined);
        active?.free();
    }
};

/**
 * Reads exactly the provided number of bytes from the device, keeping
 * any extra bytes received for the next read.
 *
 * @param reader The reader of the serial port.
 * @param buffer The bytes received and not consumed yet.
 * @param count The number of bytes to be read.
 * @param timeout The time (in milliseconds) to wait for each chunk.
 * @returns The bytes read from the device.
 */
const readExact = async (
    reader: ReadableStreamDefaultReader<Uint8Array>,
    buffer: SerialBuffer,
    count: number,
    timeout: number
): Promise<Uint8Array> => {
    while (buffer.data.length < count) {
        const { value, done } = await readTimeout(reader, timeout);
        if (done || !value) {
            throw new Error("The connection to the device was closed");
        }
        const data = new Uint8Array(buffer.data.length + value.length);
        data.set(buffer.data);
        data.set(value, buffer.data.length);
        buffer.data = data;
    }
    const data = buffer.data.slice(0, count);
    buffer.data = buffer.data.slice(count);
    return data;
};

/**
 * Reads the next chunk from the device, failing in case it does not
 * reply within the provided timeout.
 *
 * @param reader The reader of the serial port.
 * @param timeout The time (in milliseconds) to wait for the chunk.
 * @returns The result of the read operation.
 */
const readTimeout = async (
    reader: ReadableStreamDefaultReader<Uint8Array>,
    timeout: number
): Promise<ReadableStreamReadResult<Uint8Array>> => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
        return await Promise.race([
            reader.read(),
            new Promise<never>((_, reject) => {
                timer = setTimeout(
                    () =>
                        reject(
                            new Error(
                                "The device is not responding, check that it runs the L firmware"
                            )
                        ),
                    timeout
                );
            })
        ]);
    } finally {
        clearTimeout(timer);
    }
};

