    validateState?(data: Uint8Array, validation: Validation): Promise<void>;

    pauseVideo?(): void;

    resumeVideo?(): void;

    getVideoState?(): boolean;

    pauseAudio?(): void;

    resumeAudio?(): void;

    getAudioState?(): boolean;

    /**
