/**
 * Abstract interface for the persistence of opaque values, used
 * by the core to store both the battery backed RAM and the
 * settings of the emulator.
 *
 * Allows the embedder to provide its own persistence strategy
 * instead of being bound to the Web Storage API.
 *
 * The operations are synchronous as they are run from the tick
 * operation of the emulator, meaning that asynchronous back-ends
 * (eg: IndexedDB) have to be fronted by an in memory cache that
 * is flushed out of band.
 */
export interface StorageAdapter {
    /**
     * Obtains the value currently stored under the provided key.
     *
     * @param key The key of the value to be retrieved.
     * @returns The value stored under the key or null in case no
     * value is currently stored for it.
     */
    getItem(key: string): string | null;

    /**
     * Stores the provided value under the provided key, replacing
     * any value that may have been previously stored.
     *
     * @param key The key under which the value is stored.
     * @param value The value to be stored.
     */
    setItem(key: string, value: string): void;
}

/**
 * Storage adapter backed by the Web Storage API, using the
 * `localStorage` of the current window as the persistence layer.
 *
 * This is the default adapter used whenever the core runs in a
 * browser environment that exposes the `localStorage` object.
 */
export class LocalStorageAdapter implements StorageAdapter {
    getItem(key: string): string | null {
        return localStorage.getItem(key);
    }

    setItem(key: string, value: string) {
        localStorage.setItem(key, value);
    }
}

/**
 * Storage adapter that discards every write operation and never
 * returns a stored value, to be used whenever persistence is
 * either not available or not wanted.
 */
export class NullStorageAdapter implements StorageAdapter {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    getItem(key: string): string | null {
        return null;
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    setItem(key: string, value: string) {}
}

/**
 * Builds the default storage adapter for the current environment,
 * using the Web Storage API whenever it's available and falling
 * back to a null (no-op) adapter otherwise.
 *
 * @returns The storage adapter to be used by default.
 */
export const defaultStorage = (): StorageAdapter =>
    typeof localStorage === "undefined"
        ? new NullStorageAdapter()
        : new LocalStorageAdapter();

import assert from "assert";

import { PALETTES, PALETTES_MAP } from "../../ts/palettes";

describe("Palettes", function () {
    describe("#PALETTES", function () {
        it("should be able to provide the complete set of palettes", () => {
            assert.ok(PALETTES.length > 0);
        });

        it("should be able to provide four colors per palette", () => {
            PALETTES.forEach((palette) => {
                assert.strictEqual(palette.colors.length, 4);
            });
        });

        it("should be able to provide unique palette names", () => {
            const names = PALETTES.map((palette) => palette.name);
            assert.strictEqual(new Set(names).size, names.length);
        });

        it("should be able to provide valid hexadecimal colors", () => {
            PALETTES.forEach((palette) => {
                palette.colors.forEach((color) => {
                    assert.match(color, /^[0-9a-f]{6}$/);
                });
            });
        });
    });

    describe("#PALETTES_MAP", function () {
        it("should be able to index every palette by name", () => {
            assert.strictEqual(
                Object.keys(PALETTES_MAP).length,
                PALETTES.length
            );
            PALETTES.forEach((palette) => {
                assert.strictEqual(PALETTES_MAP[palette.name], palette);
            });
        });
    });
});

import assert from "assert";

import {
    defaultStorage,
    LocalStorageAdapter,
    NullStorageAdapter
} from "../../ts/storage";

/**
 * The in memory items of the local storage stub, used to verify
 * the operations of the Web Storage API backed adapter.
 */
let items: Record<string, string> = {};

describe("Storage", function () {
    beforeEach(() => {
        items = {};
        global.localStorage = {
            getItem: (key: string) => (key in items ? items[key] : null),
            setItem: (key: string, value: string) => {
                items[key] = value;
            }
        } as unknown as Storage;
    });

    afterEach(() => {
        delete (global as { localStorage?: Storage }).localStorage;
    });

    describe("#getItem()", function () {
        it("should be able to read a stored value", () => {
            items["title"] = "value";
            const storage = new LocalStorageAdapter();
            assert.strictEqual(storage.getItem("title"), "value");
        });

        it("should be able to return null for a missing value", () => {
            const storage = new LocalStorageAdapter();
            assert.strictEqual(storage.getItem("missing"), null);
        });

        it("should be able to always return null when null backed", () => {
            const storage = new NullStorageAdapter();
            storage.setItem("title", "value");
            assert.strictEqual(storage.getItem("title"), null);
        });
    });

    describe("#setItem()", function () {
        it("should be able to store a value", () => {
            const storage = new LocalStorageAdapter();
            storage.setItem("title", "value");
            assert.strictEqual(items["title"], "value");
        });

        it("should be able to replace a stored value", () => {
            const storage = new LocalStorageAdapter();
            storage.setItem("title", "first");
            storage.setItem("title", "second");
            assert.strictEqual(items["title"], "second");
        });

        it("should be able to discard a value when null backed", () => {
            const storage = new NullStorageAdapter();
            storage.setItem("title", "value");
            assert.deepStrictEqual(items, {});
        });
    });

    describe("#defaultStorage()", function () {
        it("should be able to use the Web Storage API when available", () => {
            assert.ok(defaultStorage() instanceof LocalStorageAdapter);
        });

        it("should be able to fall back when no Web Storage API", () => {
            delete (global as { localStorage?: Storage }).localStorage;
            assert.ok(defaultStorage() instanceof NullStorageAdapter);
        });
    });
});
